input.command:
sed -i '$d' tests/rotate_test.sh
cat >> tests/rotate_test.sh <<'EOF'

# LOG-31: only the newest keep (config/rotate.conf) generations remain, locally and in the archive
d=$(mktemp -d); mkdir -p "$d/logs"
for i in 1 2 3 4 5 6; do echo "g$i" > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 2026100$i; done
echo keepme > "$d/logs/other.log.9"; echo keepme > "$d/archive/app.log.notadate"; echo keepme > "$d/archive/other.log.20200101"
bash bin/rotate "$d/logs" "$d/archive" app.log 20261007
[ "$(ls "$d/logs" | grep -c '^app.log\.[0-9]*$')" = 3 ] || { echo "local count"; fail=1; }
[ "$(cat "$d/logs/app.log.3")" = g5 ] || { echo "local newest kept"; fail=1; }
[ ! -e "$d/logs/app.log.4" ] || { echo "local old removed"; fail=1; }
[ "$(ls "$d/archive" | grep -c '^app.log\.[0-9]\{8\}$')" = 3 ] || { echo "archive count"; fail=1; }
[ -e "$d/archive/app.log.20261007" ] && [ ! -e "$d/archive/app.log.20261003" ] || { echo "archive newest kept"; fail=1; }
[ -e "$d/logs/other.log.9" ] && [ -e "$d/archive/app.log.notadate" ] && [ -e "$d/archive/other.log.20200101" ] || { echo "unrelated files touched"; fail=1; }
rm -rf "$d"
exit $fail
EOF
tail -22 tests/rotate_test.sh | head -3; bash tests/rotate_test.sh; echo rc=$?
